function largestOf(numbers) {
  let largest = 0; // BUG: wrong seed; also no empty-list handling
  for (let i = 0; i < numbers.length; i++) {
    if (numbers[i] > largest) largest = numbers[i];
  }
  return largest;
}

grading.setup:
function assert(cond, msg){ if(!cond){ console.log('FAIL: '+msg); throw new Error(msg); } }
assert(largestOf([3,9,2,7]) === 9, 'positives');
assert(largestOf([-5,-3,-1]) === -1, 'all negatives');
assert(largestOf([5,5,5,5]) === 5, 'all equal');
assert(largestOf([7]) === 7, 'single element');
assert(largestOf([]) === null, 'empty list');
